import{_ as t,o as s,c as a,a3 as o}from"./chunks/framework.cNy3aYYk.js";const g=JSON.parse('{"title":"Customizable tenant dashboard layouts — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Customizable tenant dashboard layouts — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/dashboard-layout-customize-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Customizable tenant dashboard layouts — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/dashboard-layout-customize-production-readiness"}]]},"headers":[],"relativePath":"deployment/dashboard-layout-customize-production-readiness.md","filePath":"deployment/dashboard-layout-customize-production-readiness.md","lastUpdated":1792536698000}'),d={name:"deployment/dashboard-layout-customize-production-readiness.md"};function r(i,e,n,l,c,h){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="customizable-tenant-dashboard-layouts-—-production-readiness-audit" tabindex="-1">Customizable tenant dashboard layouts — Production Readiness Audit <a class="header-anchor" href="#customizable-tenant-dashboard-layouts-—-production-readiness-audit" aria-label="Permalink to &quot;Customizable tenant dashboard layouts — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-21</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> — Pest <strong>14/14</strong> dashboard widget + layout; headed Playwright <strong>1/1</strong> (one login session)</td></tr><tr><td><strong>Scope</strong></td><td>Per-user show/hide + reorder of entitled dashboard widgets; platform templates; server-persisted <code>users.dashboard_layout</code></td></tr><tr><td><strong>Catalog</strong></td><td>No bump (platform shell feature)</td></tr><tr><td><strong>Companion</strong></td><td><a href="/user-guide/tenant-application">Tenant application user guide</a> · <a href="/api/tenant-v1-dashboard">Tenant dashboard API</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Workspace users with <code>dashboard.view</code> can open <strong>Customize</strong> on the tenant Dashboard, apply a job template (Balanced, Sales rep, Sales manager, Service desk, Project ops, Finance ops, CRM lite), show/hide widgets, drag-reorder them, and save. Preferences are stored per user. <strong>Module entitlement + Spatie permission always win</strong> — layouts never grant access. Newly entitled widgets stay hidden until the user opts in (<code>new_widget_ids</code>).</p><p><strong>Go / No-Go:</strong> <strong>Go.</strong> Migrate-only (<code>users.dashboard_layout</code>). Deploy Backend and Frontend together; hard-refresh SPA.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze</td><td><strong>Pass</strong> — AppLayout + existing widget registry; no parallel shell</td></tr><tr><td>Eligibility still filters widgets</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Default (no preference) shows all eligible widgets</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Custom items persist show/hide + order</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Template apply only includes eligible ids</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Unknown <code>template_id</code> → 422</td><td><strong>Pass</strong> (Pest + headed API check)</td></tr><tr><td>Missing <code>dashboard.view</code> → 403</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Headed one session: invalid template 422, Sales rep template, hide High Priority, Show all restore</td><td><strong>Pass</strong> (<code>npm run test:e2e:tenant-dashboard:customize:headed</code>)</td></tr></tbody></table><hr><h2 id="security-summary" tabindex="-1">Security summary <a class="header-anchor" href="#security-summary" aria-label="Permalink to &quot;Security summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Status</th></tr></thead><tbody><tr><td>Layout update requires <code>dashboard.view</code></td><td>Pass</td></tr><tr><td>Widget ids outside the customizable catalog are dropped</td><td>Pass</td></tr><tr><td>Ineligible module/permission widgets never appear even if pinned</td><td>Pass</td></tr><tr><td>Preference JSON stores layout only (no payload data)</td><td>Pass</td></tr><tr><td>Chrome widgets (<code>activity_feed</code>, <code>notifications</code>, <code>quick_actions</code>) are not user-layouted</td><td>Pass</td></tr></tbody></table><hr><h2 id="findings-disposition" tabindex="-1">Findings disposition <a class="header-anchor" href="#findings-disposition" aria-label="Permalink to &quot;Findings disposition&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Item</th><th>Disposition</th></tr></thead><tbody><tr><td><strong>F1</strong></td><td>Medium</td><td>Existing tenant dashboard e2e expected removed <strong>Pipeline activity</strong> section after layout unification</td><td><strong>Fixed</strong> — assertions use <strong>Workspace insights</strong> + Customize button; demo layout reset before load</td></tr><tr><td><strong>F2</strong></td><td>Medium</td><td><code>.env.e2e.local</code> did not override <code>.env.e2e</code> (dotenv default) so Windows DNS workarounds never applied</td><td><strong>Fixed</strong> — <code>playwright.config.ts</code> loads <code>.env.e2e.local</code> with <code>override: true</code></td></tr><tr><td><strong>F3</strong></td><td>Medium</td><td>Browser could not resolve Herd <code>elosync-backend.test</code> (offline banner) while Node APIRequestContext could use <code>127.0.0.1</code> + Host</td><td><strong>Fixed</strong> — <code>e2e/helpers/herd-dns-bypass.ts</code> routes browser traffic + prefers same-origin Vite <code>/api</code> proxy; document local <code>E2E_API_URL</code> / <code>E2E_API_HOST</code></td></tr><tr><td><strong>I1</strong></td><td>Info</td><td>Sonner success toast can dismiss before Playwright asserts text</td><td><strong>Accepted</strong> — headed test waits for PUT <code>/dashboard/layout</code> response + sheet close</td></tr></tbody></table><hr><h2 id="headed-browser-coverage" tabindex="-1">Headed browser coverage <a class="header-anchor" href="#headed-browser-coverage" aria-label="Permalink to &quot;Headed browser coverage&quot;">​</a></h2><p><code>npm run test:e2e:tenant-dashboard:customize:headed</code> on 2026-10-21. Result: <strong>1 passed</strong> (one serial session).</p><p>One demo-tenant login, one page session:</p><ol><li>Reset layout to all-visible via API (stable baseline on shared demo user)</li><li><code>PUT</code> unknown <code>template_id</code> → <strong>422</strong> validation error</li><li>Open Dashboard → <strong>Customize</strong> → Cancel (no change)</li><li>Apply <strong>Sales rep</strong> template → Save → <code>template_id=sales_rep</code>; <code>lead_sources</code> not visible</li><li>Hide <strong>High priority deals</strong> → Save → heading gone; <code>template_id</code> cleared</li><li><strong>Show all</strong> → Save → High Priority returns</li><li>Restore full-visible layout in <code>finally</code></li></ol><p>Also: <code>npm run test:e2e:tenant-dashboard</code> (widget chrome + sidebar) after layout reset.</p><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><ol><li><code>php artisan migrate --force</code> (adds nullable <code>users.dashboard_layout</code>). Do not <code>db:seed</code>.</li><li>Deploy Backend, then Frontend production build; hard-refresh SPA.</li><li>Smoke: open Dashboard → Customize → apply Sales rep → Save → confirm widgets change → Show all → Save.</li></ol><hr><h2 id="local-e2e-notes-windows-herd" tabindex="-1">Local e2e notes (Windows + Herd) <a class="header-anchor" href="#local-e2e-notes-windows-herd" aria-label="Permalink to &quot;Local e2e notes (Windows + Herd)&quot;">​</a></h2><p>When Node/Chrome cannot resolve <code>.test</code> DNS:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># .env.e2e.local</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">E2E_BASE_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=http://localhost:5173</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">E2E_API_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=http://127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">E2E_API_HOST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=elosync-backend.test</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">E2E_SKIP_WEBSERVER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1</span></span></code></pre></div><p>Serve the SPA with same-origin API so Vite’s <code>/api</code> proxy applies:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VITE_API_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://localhost:5173</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5173</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --strictPort</span></span></code></pre></div>`,28)])])}const u=t(d,[["render",r]]);export{g as __pageData,u as default};
